//! The functions the managed engine calls into. `NativeApi` is the source of the managed side's
//! `managed/UnityEngine/Runtime/NativeApi.g.cs`, generated by the test at the end; it is versioned.
use crate::{
    audio::{
        Clip, SourceParams,
        protocol::{
            AudioClipInfo, AudioFramePacket, AudioSourceCommand, AudioSourcePacket,
            AudioSourceState, AudioStatus, Callback,
        },
    },
    plugin_api,
    realtime_gi::{GiFrame, GiLight},
    render_protocol::{
        ImportedTextureInfo, MaterialPacket, MeshPacket, TexturePacket, commands, handle, owned,
    },
    state,
};
use std::ffi::c_void;

/// 13: render protocol 6, texture handle element bits (`render_protocol::handle`).
/// 14: `wrap_w` at the end of `TexturePacket` and `ImportedTextureInfo`.
/// 15: render protocol 7 (buffer copies, counters, indirect dispatches) and `read_texture`.
/// 16: filter component descriptors at the end of `AudioSourcePacket`.
/// 17: render protocol 8 (`DrawIndices`, opcode 28), without the filter descriptors of 16.
/// 18: both: the filter descriptors of 16 and render protocol 8 of 17.
/// 19: render protocol 9 (`CopyDepth`, opcode 29).
/// 20: `AudioReverbFilter` descriptors (kind 4 and 14 reverb parameters per descriptor).
/// 21: the reverb zone descriptor at the end of `AudioFramePacket`; `reverb_zone_mix` is the
/// source's send gain.
/// 22: render protocols 10 and 11 (32-bit indices and logical instance IDs).
/// 23: AudioDistortionFilter kind 5, Level in the existing cutoff field.
/// 26: measured mixer Normalize parameters in the group configuration JSON.
/// 27: measured mixer Pitch Shifter parameters in the group configuration JSON.
/// 28: render protocol 12 (shared property arrays, `MeshInstance` elements).
/// 29: cached display and IME versions at the end of `FrameInput`.
/// 30: decoded audio resampling flag.
/// 31: the reported `TextureFormat` at the end of `ImportedTextureInfo`.
/// 32: render protocol 13 (mesh GPU bindings, gizmo normal transforms and float4 mesh colors).
/// 33: source component tail timing across partial device periods.
/// 34: render protocol 14 (persistent direct-draw instance multiplier).
/// 35: texture packet flag for deferred automatic mip visibility.
/// 36: source-loop listener pose snapshots for spatial audio.
/// 37: `audio_decode_clip` (downloaded audio files).
/// 38: prepared callback buffers for closing captured audio output.
/// 39: retained MSAA resolve images, explicit resolves and current-attachment read flags.
/// 40: parameterised mixer Pitch Shifter FFT size.
/// 41: native rendering plugins (render protocol 15's `Plugin` command, opcode 34; the plugin
/// interface, native texture pointers and external textures).
/// 42: legacy glyph floating-point bearings and explicit rendering modes.
/// 43: compatibility-selected zone initialization and parameter transitions.
/// 44: mixer Pitch Shifter Max channels.
/// 45: precomputed realtime GI (`gi_update`, `gi_read_atlas`, `gi_set_material`,
/// `gi_set_emissive`, `gi_realtime_uvs`).
/// 46: driver capabilities and the active speaker mode in the audio settings reply.
/// 47: source filter component activation flags and the component reset command.
/// 48: `GiFrame.update_threshold` (DynamicGI.updateThreshold).
/// 49: `gi_read_probes`, light probes lit by precomputed realtime GI.
/// 50: the `ScreenStandIn` render command (opcode 35).
/// 51: `gi_set_environment`; `GiFrame` without its flat environment color.
/// 52: `GiFrame.directional` and `gi_read_directionality` (directional realtime lightmaps).
/// 53: `realtime_gi::GiLight` with its falloff type.
/// 54: `plugin_frame`, `plugin_events`, `plugin_query` (native plugins' profiler callbacks, event
/// queue and rendering extension query).
/// 55: `external_texture` takes the mip levels where the declared size and color space were.
/// 56: retained disabled audio components through the filter stage bypass bit, and the
/// explicit Stop history flag.
pub const NATIVE_API_VERSION: u32 = 57;

/// A legacy glyph bitmap in pixels, with its logical top after bitmap synthesis.
#[repr(C)]
#[derive(Debug, Clone, Copy, Default)]
pub struct GlyphInfo {
    pub advance: f32,
    pub left: i32,
    pub top: f32,
    pub width: i32,
    pub height: i32,
}

/// A glyph rendered by index (`font_render_glyph`): the bitmap as in [`GlyphInfo`] plus the
/// outline's unrounded control box in pixels, which TextCore reports as the glyph metrics.
#[repr(C)]
#[derive(Debug, Clone, Copy, Default)]
pub struct GlyphOutlineInfo {
    pub advance: f32,
    pub x_min: f32,
    pub y_min: f32,
    pub x_max: f32,
    pub y_max: f32,
    pub left: i32,
    pub top: i32,
    pub width: i32,
    pub height: i32,
}

/// A buffer handed to the managed side; it gives it back to `free_buffer`.
#[repr(C)]
pub struct NativeBuffer {
    pub data: *mut u8,
    pub length: i64,
}

impl NativeBuffer {
    pub fn from_vec(bytes: Vec<u8>) -> Self {
        let boxed = bytes.into_boxed_slice();
        let length = boxed.len() as i64;
        let data = Box::into_raw(boxed) as *mut u8;
        Self { data, length }
    }

    pub const fn empty() -> Self {
        Self {
            data: std::ptr::null_mut(),
            length: 0,
        }
    }
}

#[repr(C)]
pub struct NativeApi {
    pub version: u32,
    /// (level, UTF-8 text, length): writes a console line.
    pub log: extern "C" fn(level: i32, text: *const u8, length: i32),
    /// (method, length, request, length, out response): a control call with JSON in and out;
    /// returns 0 on success, else the response holds an error message.
    pub call: extern "C" fn(*const u8, i32, *const u8, i32, *mut NativeBuffer) -> i32,
    /// Releases a buffer the native side returned.
    pub free_buffer: extern "C" fn(NativeBuffer),
    /// (asset path or guid, length, out documents): the YAML documents of a scene, prefab or
    /// asset file with prefab instances expanded, in the binary node encoding.
    pub load_documents: extern "C" fn(*const u8, i32, *mut NativeBuffer) -> i32,
    /// (command stream, length): executes rendering commands in order (render_commands.rs).
    pub submit_commands: extern "C" fn(*const u8, i64),
    pub upload_mesh: extern "C" fn(u64, *const MeshPacket),
    pub release_mesh: extern "C" fn(u64),
    pub upload_texture: extern "C" fn(u64, *const TexturePacket),
    pub import_texture: extern "C" fn(u64, *const u8, i32, *mut ImportedTextureInfo) -> i32,
    pub release_texture: extern "C" fn(u64),
    pub update_material: extern "C" fn(u64, *const MaterialPacket),
    pub release_material: extern "C" fn(u64),
    /// (font handle, code point, pixel size, FontStyle, out info, out coverage): 1 when the font
    /// has the glyph, else 0. The coverage is `width * height` bytes, top row first.
    pub font_glyph: extern "C" fn(u64, u32, f32, i32, *mut GlyphInfo, *mut NativeBuffer) -> i32,
    // Version 4: audio (docs/AUDIO.md).
    pub audio_import_clip: extern "C" fn(u64, *const u8, i32, *mut AudioClipInfo) -> i32,
    pub audio_create_clip: extern "C" fn(u64, i32, i32, i32, i32),
    pub audio_clip_data: extern "C" fn(u64, i32, *mut f32, i32, i32) -> i32,
    pub audio_release_clip: extern "C" fn(u64),
    pub audio_update_source: extern "C" fn(u64, *const AudioSourcePacket),
    pub audio_source_command: extern "C" fn(u64, *const AudioSourceCommand) -> i32,
    pub audio_source_state: extern "C" fn(u64, *mut AudioSourceState),
    pub audio_release_source: extern "C" fn(u64),
    pub audio_update_group: extern "C" fn(u64, f32, f32),
    pub audio_frame: extern "C" fn(*const AudioFramePacket, *mut AudioStatus),
    pub audio_dsp_time: extern "C" fn() -> f64,
    pub audio_output_data: extern "C" fn(u64, i32, *mut f32, i32, i32) -> i32,
    pub audio_set_callback: extern "C" fn(Option<Callback>),
    // Version 5: image bytes (ImageConversion).
    /// (bytes, length, out width, out height, out is-JPEG, out RGBA8 rows bottom first): 1 when decoded.
    pub image_decode:
        extern "C" fn(*const u8, i32, *mut i32, *mut i32, *mut i32, *mut NativeBuffer) -> i32,
    /// (encoding: 0 PNG, 1 JPG, 2 TGA, 3 EXR; JPG quality; pixels; width; height; pixels are float
    /// RGBA (else RGBA8), rows bottom first; out file bytes): 1 when encoded.
    pub image_encode: extern "C" fn(i32, i32, *const u8, i32, i32, i32, *mut NativeBuffer) -> i32,
    // Version 6: glyphs by index (TextCore's FontEngine).
    /// (font handle, code point): the glyph index, 0 when the face lacks it.
    pub font_glyph_index: extern "C" fn(u64, u32) -> u32,
    /// (font handle, glyph index, pixel size, SDF padding, out info, out pixels): 1 when the face
    /// has the glyph. With a negative padding the pixels are coverage, as `font_glyph`'s; else a
    /// signed distance field grown by the padding on every side (`FontFace::render_glyph_sdf`).
    pub font_render_glyph:
        extern "C" fn(u64, u32, f32, i32, *mut GlyphOutlineInfo, *mut NativeBuffer) -> i32,
    // Version 7: no new entries; `FrameInput` gained the frame's ordered key events.
    // Version 9: the command stream replaces the frame packet.
    /// (texture handle, 0 for the screen; x, y, width, height; float; out pixels): 1 with the
    /// rectangle's RGBA pixels, rows bottom first, 4 bytes each (16 when float).
    pub read_pixels: extern "C" fn(u64, i32, i32, i32, i32, i32, *mut NativeBuffer) -> i32,
    // Version 10: buffers and compute (render_commands.rs).
    /// (buffer handle, offset, size, out bytes): 1 with the buffer's bytes after everything
    /// submitted.
    pub read_buffer: extern "C" fn(u64, i64, i64, *mut NativeBuffer) -> i32,
    // Version 12: per-frame calls without JSON.
    /// (Unity family, length, out, capacity): the frame's gamepad and joystick input
    /// (`gamepads::state`), written when it fits; returns its size, 0 without SDL.
    pub gamepads_state: extern "C" fn(*const u8, i32, *mut u8, i32) -> i32,
    /// (decoder, frame, the Y, U and V plane textures, out error): 1 when the frame was decoded
    /// into the planes, 0 when it was not (yet), -1 on an error (its message in the buffer).
    pub video_frame: extern "C" fn(u64, i64, *const u64, *mut NativeBuffer) -> i32,
    // Version 15: texture levels and layers.
    /// (texture handle, mip level, layer: an array slice, cube face or volume depth slice; x, y,
    /// width, height; float; out pixels): 1 with the rectangle's pixels as `read_pixels` gives
    /// them, 0 when the texture has no such level or layer.
    pub read_texture:
        extern "C" fn(u64, i32, i32, i32, i32, i32, i32, i32, *mut NativeBuffer) -> i32,
    // Version 37: downloaded audio.
    /// (clip handle, file bytes, length, Unity `AudioType`, header only, out info): 0 when the
    /// file decodes as that type (`unbound_assets::audio_download`) into the clip, the info's
    /// compression format being the file's coding, or, header only, when a partial WAV
    /// announces its format and length (no clip is made); else 1.
    pub audio_decode_clip: extern "C" fn(u64, *const u8, i32, i32, i32, *mut AudioClipInfo) -> i32,
    // Version 41: native rendering plugins (`plugin_api`).
    /// (a library's `UnityPluginLoad`): calls it with the plugin interfaces, with the plugins'
    /// OpenGL context current when there is one.
    pub plugin_load: extern "C" fn(*const c_void),
    /// (sink: LogType, UTF-8 text, length): where plugin log messages go (`IUnityLog`, the
    /// renderer's checks after plugin callbacks).
    pub plugin_set_log: extern "C" fn(Option<extern "C" fn(i32, *const u8, i32)>),
    /// The application's end: the plugins' device Shutdown events.
    pub plugin_shutdown: extern "C" fn(),
    /// (texture handle, depth buffer): the OpenGL texture name that native plugins see for the
    /// texture (or its depth buffer), sharing its memory with the renderer; 0 when there is no
    /// plugin OpenGL interop or the texture cannot be shared.
    pub native_texture: extern "C" fn(u64, i32) -> u64,
    /// (texture handle, OpenGL texture name, mip levels, out error): makes the texture show the
    /// named native texture through that many of its levels (`Texture2D.CreateExternalTexture`,
    /// `UpdateExternalTexture`; version 55: the levels, where the declared size and color space
    /// were, which the native texture decides); 0 on success, else the buffer holds the reason.
    pub external_texture: extern "C" fn(u64, u64, i32, *mut NativeBuffer) -> i32,
    // Version 43: precomputed realtime GI (`realtime_gi`; loaded with the `realtime-gi-load`
    // control call).
    /// (scene, frame, lights, count, out error): one frame's update; `realtime_gi::UPDATE_*`
    /// bits, or -1 with the reason in the buffer.
    pub gi_update:
        extern "C" fn(u64, *const GiFrame, *const GiLight, i32, *mut NativeBuffer) -> i32,
    /// (scene, atlas, out RGBA half floats, capacity in halves): the atlas's texels written, or -1.
    pub gi_read_atlas: extern "C" fn(u64, i32, *mut u16, i32) -> i32,
    /// (scene, out coefficients, capacity in floats): the light probes its probe sets light, 27
    /// coefficients each (red, green, blue) by LightProbes index, the others left as they are;
    /// the number of probes the scene's probe sets span, or -1.
    pub gi_read_probes: extern "C" fn(u64, *mut f32, i32) -> i32,
    /// (scene, system, kind: 0 albedo RGBA8, 1 emission RGBA float; texels, length in bytes,
    /// out error): a system's material texture as its meta passes render it; 0 on success.
    pub gi_set_material: extern "C" fn(u64, i32, i32, *const u8, i64, *mut NativeBuffer) -> i32,
    /// (scene, system, renderer within the system, linear RGB, out error):
    /// DynamicGI.SetEmissive; 0 on success.
    pub gi_set_emissive: extern "C" fn(u64, i32, i32, *const f32, *mut NativeBuffer) -> i32,
    /// (scene, environment faces: 6 x 8 x 8 linear RGB, float count, out error): the
    /// environment precomputed realtime GI reads (`realtime_gi::set_environment`); 0 on success.
    pub gi_set_environment: extern "C" fn(u64, *const f32, i32, *mut NativeBuffer) -> i32,
    /// (scene, system, renderer within the system, world positions (3 floats each), lightmap UVs
    /// (2 floats each), vertex count, triangle indices, index count, world units per texel,
    /// minimum chart size in texels, out UVs (2 floats per vertex), out error): the renderer's
    /// realtime lightmap UVs (`realtime_gi::realtime_uvs`); 0 on success.
    pub gi_realtime_uvs: extern "C" fn(
        u64,
        i32,
        i32,
        *const f32,
        *const f32,
        i32,
        *const u32,
        i32,
        f32,
        i32,
        *mut f32,
        *mut NativeBuffer,
    ) -> i32,
    // Version 52: directional realtime lightmaps.
    /// (scene, atlas, out RGBA8 texels, capacity in bytes): the atlas's directionality texels
    /// written (0 while the scene's lightmaps are not directional, and until every system of
    /// the atlas has solved its directionality since they became so), or -1.
    pub gi_read_directionality: extern "C" fn(u64, i32, *mut u8, i32) -> i32,
    // Version 53: a realtime GI light carries its falloff type (`realtime_gi::GiLight`); no new
    // entry.
    // Version 54: native plugins' profiler callbacks, event queue and rendering extension query.
    /// A frame ended: the native plugins' profiler frame callbacks (`IUnityProfilerCallbacks`).
    pub plugin_frame: extern "C" fn(),
    /// A frame began: the events native plugins sent through `IUnityEventQueue`.
    pub plugin_events: extern "C" fn(),
    /// (a plugin's `UnityRenderingExtQuery`, the query): asks it, with the plugins' graphics
    /// context current; its answer.
    pub plugin_query: extern "C" fn(*const c_void, i32) -> i32,
}

pub fn api() -> NativeApi {
    NativeApi {
        version: NATIVE_API_VERSION,
        log,
        call,
        free_buffer,
        load_documents,
        submit_commands,
        upload_mesh,
        release_mesh,
        upload_texture,
        import_texture,
        release_texture,
        update_material,
        release_material,
        font_glyph,
        audio_import_clip,
        audio_create_clip,
        audio_clip_data,
        audio_release_clip,
        audio_update_source,
        audio_source_command,
        audio_source_state,
        audio_release_source,
        audio_update_group,
        audio_frame,
        audio_dsp_time,
        audio_output_data,
        audio_set_callback,
        image_decode,
        image_encode,
        font_glyph_index,
        font_render_glyph,
        read_pixels,
        read_buffer,
        gamepads_state,
        video_frame,
        read_texture,
        audio_decode_clip,
        plugin_load,
        plugin_set_log,
        plugin_shutdown,
        native_texture,
        external_texture,
        gi_update,
        gi_read_atlas,
        gi_read_probes,
        gi_set_material,
        gi_set_emissive,
        gi_set_environment,
        gi_realtime_uvs,
        gi_read_directionality,
        plugin_frame,
        plugin_events,
        plugin_query,
    }
}

/// Runs a fallible call, writing its error (or panic) into `error`: 0 or the call's value on
/// success, -1 on failure.
fn reported(error: *mut NativeBuffer, f: impl FnOnce() -> anyhow::Result<i32>) -> i32 {
    let message = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(Ok(value)) => return value,
        Ok(Err(e)) => format!("{e:#}"),
        Err(_) => "the realtime GI update panicked".to_string(),
    };
    if !error.is_null() {
        unsafe { *error = NativeBuffer::from_vec(message.into_bytes()) };
    }
    -1
}

extern "C" fn gi_update(
    scene: u64,
    frame: *const GiFrame,
    lights: *const GiLight,
    count: i32,
    error: *mut NativeBuffer,
) -> i32 {
    reported(error, || {
        anyhow::ensure!(!frame.is_null(), "no frame");
        let frame = unsafe { &*frame };
        let lights = if lights.is_null() || count <= 0 {
            &[][..]
        } else {
            unsafe { std::slice::from_raw_parts(lights, count as usize) }
        };
        crate::realtime_gi::update(scene, frame, lights)
    })
}

extern "C" fn gi_set_environment(
    scene: u64,
    faces: *const f32,
    count: i32,
    error: *mut NativeBuffer,
) -> i32 {
    reported(error, || {
        anyhow::ensure!(!faces.is_null() && count >= 0, "no environment");
        let faces = unsafe { std::slice::from_raw_parts(faces, count as usize) };
        crate::realtime_gi::set_environment(scene, faces)?;
        Ok(0)
    })
}

extern "C" fn gi_read_atlas(scene: u64, atlas: i32, out: *mut u16, capacity: i32) -> i32 {
    if out.is_null() || capacity <= 0 || atlas < 0 {
        return -1;
    }
    let out = unsafe { std::slice::from_raw_parts_mut(out, capacity as usize) };
    reported(std::ptr::null_mut(), || {
        Ok(crate::realtime_gi::read_atlas(scene, atlas as usize, out)? as i32)
    })
}

extern "C" fn gi_read_directionality(scene: u64, atlas: i32, out: *mut u8, capacity: i32) -> i32 {
    if out.is_null() || capacity <= 0 || atlas < 0 {
        return -1;
    }
    let out = unsafe { std::slice::from_raw_parts_mut(out, capacity as usize) };
    reported(std::ptr::null_mut(), || {
        Ok(crate::realtime_gi::read_directionality(scene, atlas as usize, out)? as i32)
    })
}

extern "C" fn gi_read_probes(scene: u64, out: *mut f32, capacity: i32) -> i32 {
    if out.is_null() || capacity < 0 {
        return -1;
    }
    let out = unsafe { std::slice::from_raw_parts_mut(out, capacity as usize) };
    reported(std::ptr::null_mut(), || {
        Ok(crate::realtime_gi::read_probes(scene, out)? as i32)
    })
}

extern "C" fn gi_set_material(
    scene: u64,
    system: i32,
    kind: i32,
    bytes: *const u8,
    length: i64,
    error: *mut NativeBuffer,
) -> i32 {
    reported(error, || {
        anyhow::ensure!(
            system >= 0 && !bytes.is_null() && length >= 0,
            "a bad material texture"
        );
        let bytes = unsafe { std::slice::from_raw_parts(bytes, length as usize) };
        crate::realtime_gi::set_material(scene, system as usize, kind, bytes)?;
        Ok(0)
    })
}

extern "C" fn gi_set_emissive(
    scene: u64,
    system: i32,
    renderer: i32,
    rgb: *const f32,
    error: *mut NativeBuffer,
) -> i32 {
    reported(error, || {
        anyhow::ensure!(
            system >= 0 && renderer >= 0 && !rgb.is_null(),
            "a bad renderer or color"
        );
        let color = unsafe { [*rgb, *rgb.add(1), *rgb.add(2)] };
        crate::realtime_gi::set_emissive(scene, system as usize, renderer as usize, color)?;
        Ok(0)
    })
}

#[allow(clippy::too_many_arguments)]
extern "C" fn gi_realtime_uvs(
    scene: u64,
    system: i32,
    renderer: i32,
    positions: *const f32,
    uvs: *const f32,
    vertices: i32,
    indices: *const u32,
    index_count: i32,
    pixel_size: f32,
    min_chart_texels: i32,
    out: *mut f32,
    error: *mut NativeBuffer,
) -> i32 {
    reported(error, || {
        anyhow::ensure!(
            system >= 0
                && renderer >= 0
                && vertices >= 0
                && index_count >= 0
                && index_count % 3 == 0
                && min_chart_texels >= 0
                && !positions.is_null()
                && !uvs.is_null()
                && !indices.is_null()
                && !out.is_null(),
            "bad realtime lightmap UV arguments"
        );
        let n = vertices as usize;
        let (positions, uvs, triangles, out) = unsafe {
            (
                std::slice::from_raw_parts(positions as *const [f32; 3], n),
                std::slice::from_raw_parts(uvs as *const [f32; 2], n),
                std::slice::from_raw_parts(indices as *const [u32; 3], index_count as usize / 3),
                std::slice::from_raw_parts_mut(out, 2 * n),
            )
        };
        let input = crate::realtime_gi::UvInput {
            positions,
            uvs,
            triangles,
            pixel_size,
            min_chart_texels: min_chart_texels as u32,
        };
        crate::realtime_gi::realtime_uvs(scene, system as usize, renderer as usize, &input, out)?;
        Ok(0)
    })
}

extern "C" fn gamepads_state(family: *const u8, length: i32, out: *mut u8, capacity: i32) -> i32 {
    std::panic::catch_unwind(|| {
        let family = unsafe { std::slice::from_raw_parts(family, length.max(0) as usize) };
        let out = unsafe { std::slice::from_raw_parts_mut(out, capacity.max(0) as usize) };
        crate::gamepads::state(std::str::from_utf8(family).unwrap_or(""), out) as i32
    })
    .unwrap_or(0)
}

extern "C" fn video_frame(
    decoder: u64,
    frame: i64,
    handles: *const u64,
    error: *mut NativeBuffer,
) -> i32 {
    let handles = unsafe { [*handles, *handles.add(1), *handles.add(2)] };
    // The planes are uploads: plain handles only (render protocol 6).
    for h in handles {
        if let Err(e) = handle::plain(h, "video_frame") {
            unsafe { *error = NativeBuffer::from_vec(e.into_bytes()) };
            return -1;
        }
    }
    let result = std::panic::catch_unwind(|| crate::video::frame(decoder, frame, handles))
        .unwrap_or_else(|_| Err(anyhow::anyhow!("the decoder panicked")));
    match result {
        Ok(decoded) => decoded as i32,
        Err(e) => {
            unsafe { *error = NativeBuffer::from_vec(format!("{e:#}").into_bytes()) };
            -1
        }
    }
}

extern "C" fn font_glyph_index(font: u64, codepoint: u32) -> u32 {
    std::panic::catch_unwind(|| crate::fonts::glyph_index(font, codepoint)).unwrap_or(0)
}

extern "C" fn font_render_glyph(
    font: u64,
    glyph: u32,
    size: f32,
    sdf_padding: i32,
    info: *mut GlyphOutlineInfo,
    pixels: *mut NativeBuffer,
) -> i32 {
    let sdf = (sdf_padding >= 0).then_some(sdf_padding);
    let rendered =
        std::panic::catch_unwind(|| crate::fonts::glyph_by_index(font, glyph, size, sdf));
    unsafe {
        let Ok(Some(glyph)) = rendered else {
            *info = GlyphOutlineInfo::default();
            *pixels = NativeBuffer::empty();
            return 0;
        };
        let (x_min, y_min, x_max, y_max) = glyph.bounds;
        *info = GlyphOutlineInfo {
            advance: glyph.advance,
            x_min,
            y_min,
            x_max,
            y_max,
            left: glyph.left,
            top: glyph.top,
            width: glyph.width,
            height: glyph.height,
        };
        *pixels = if glyph.coverage.is_empty() {
            NativeBuffer::empty()
        } else {
            NativeBuffer::from_vec(glyph.coverage)
        };
    }
    1
}

extern "C" fn image_decode(
    bytes: *const u8,
    length: i32,
    width: *mut i32,
    height: *mut i32,
    jpeg: *mut i32,
    pixels: *mut NativeBuffer,
) -> i32 {
    let input = if bytes.is_null() || length <= 0 {
        &[][..]
    } else {
        unsafe { std::slice::from_raw_parts(bytes, length as usize) }
    };
    let decoded = std::panic::catch_unwind(|| unbound_assets::image_io::decode(input));
    unsafe {
        match decoded {
            Ok(Ok(image)) => {
                *width = image.width as i32;
                *height = image.height as i32;
                *jpeg = image.jpeg as i32;
                *pixels = NativeBuffer::from_vec(image.rgba);
                1
            }
            _ => {
                *width = 0;
                *height = 0;
                *jpeg = 0;
                *pixels = NativeBuffer::empty();
                0
            }
        }
    }
}

extern "C" fn image_encode(
    encoding: i32,
    quality: i32,
    pixels: *const u8,
    width: i32,
    height: i32,
    float: i32,
    output: *mut NativeBuffer,
) -> i32 {
    use unbound_assets::image_io::{Encoding, encode_rgba_f32, encode_rgba8};
    let (w, h) = (width.max(0) as u32, height.max(0) as u32);
    let count = (w as usize) * (h as usize) * 4;
    let encoded = std::panic::catch_unwind(|| {
        if pixels.is_null() || count == 0 {
            anyhow::bail!("no pixels");
        }
        if float != 0 {
            let data = unsafe { std::slice::from_raw_parts(pixels as *const f32, count) };
            if encoding == 3 {
                return encode_rgba_f32(w, h, data, false);
            }
            let bytes: Vec<u8> = data
                .iter()
                .map(|v| (v.clamp(0.0, 1.0) * 255.0 + 0.5) as u8)
                .collect();
            return encode_rgba8(encoding_of(encoding, quality), w, h, &bytes);
        }
        let data = unsafe { std::slice::from_raw_parts(pixels, count) };
        encode_rgba8(encoding_of(encoding, quality), w, h, data)
    });
    fn encoding_of(encoding: i32, quality: i32) -> Encoding {
        match encoding {
            1 => Encoding::Jpg(quality.clamp(1, 100) as u8),
            2 => Encoding::Tga,
            3 => Encoding::Exr,
            _ => Encoding::Png,
        }
    }
    unsafe {
        match encoded {
            Ok(Ok(bytes)) => {
                *output = NativeBuffer::from_vec(bytes);
                1
            }
            _ => {
                *output = NativeBuffer::empty();
                0
            }
        }
    }
}

extern "C" fn font_glyph(
    font: u64,
    codepoint: u32,
    size: f32,
    style: i32,
    info: *mut GlyphInfo,
    pixels: *mut NativeBuffer,
) -> i32 {
    let rendered = std::panic::catch_unwind(|| crate::fonts::glyph(font, codepoint, size, style));
    let Ok(Some(glyph)) = rendered else {
        unsafe {
            *info = GlyphInfo::default();
            *pixels = NativeBuffer::empty();
        }
        return 0;
    };
    unsafe {
        *info = GlyphInfo {
            advance: glyph.advance,
            left: glyph.left,
            top: glyph.top as f32 + glyph.top_offset,
            width: glyph.width,
            height: glyph.height,
        };
        *pixels = if glyph.coverage.is_empty() {
            NativeBuffer::empty()
        } else {
            NativeBuffer::from_vec(glyph.coverage)
        };
    }
    1
}

unsafe fn text<'a>(data: *const u8, length: i32) -> &'a str {
    if data.is_null() || length <= 0 {
        return "";
    }
    let bytes = unsafe { std::slice::from_raw_parts(data, length as usize) };
    std::str::from_utf8(bytes).unwrap_or("")
}

/// Unity log types: 0 error, 1 assert, 2 warning, 3 log, 4 exception.
extern "C" fn log(level: i32, data: *const u8, length: i32) {
    let message = unsafe { text(data, length) };
    match level {
        0 | 1 | 4 => tracing::error!(target: "game", "{message}"),
        2 => tracing::warn!(target: "game", "{message}"),
        _ => tracing::info!(target: "game", "{message}"),
    }
}

extern "C" fn call(
    method: *const u8,
    method_length: i32,
    request: *const u8,
    request_length: i32,
    out: *mut NativeBuffer,
) -> i32 {
    let method = unsafe { text(method, method_length) };
    let request = unsafe { text(request, request_length) };
    let result = std::panic::catch_unwind(|| state::dispatch(method, request));
    let (status, body) = match result {
        Ok(Ok(body)) => (0, body),
        Ok(Err(error)) => (1, format!("{error:#}")),
        Err(_) => (1, format!("native `{method}` panicked")),
    };
    unsafe { *out = NativeBuffer::from_vec(body.into_bytes()) };
    status
}

extern "C" fn free_buffer(buffer: NativeBuffer) {
    if buffer.data.is_null() {
        return;
    }
    unsafe {
        drop(Box::from_raw(std::ptr::slice_from_raw_parts_mut(
            buffer.data,
            buffer.length as usize,
        )));
    }
}

extern "C" fn load_documents(key: *const u8, length: i32, out: *mut NativeBuffer) -> i32 {
    let key = unsafe { text(key, length) };
    let result = std::panic::catch_unwind(|| state::load_documents(key));
    let (status, bytes) = match result {
        Ok(Ok(bytes)) => (0, bytes),
        Ok(Err(error)) => (1, format!("{error:#}").into_bytes()),
        Err(_) => (1, b"loading documents panicked".to_vec()),
    };
    unsafe { *out = NativeBuffer::from_vec(bytes) };
    status
}

extern "C" fn submit_commands(bytes: *const u8, length: i64) {
    if bytes.is_null() || length <= 0 {
        return;
    }
    let bytes = unsafe { std::slice::from_raw_parts(bytes, length as usize) };
    match commands::parse(bytes) {
        Ok(commands) => state::backend().submit_commands(commands),
        Err(error) => tracing::error!("a rendering command stream is malformed: {error}"),
    }
}

extern "C" fn read_buffer(buffer: u64, offset: i64, size: i64, out: *mut NativeBuffer) -> i32 {
    match state::backend().read_buffer(buffer, offset.max(0) as u64, size.max(0) as u64) {
        Some(bytes) => {
            unsafe { *out = NativeBuffer::from_vec(bytes) };
            1
        }
        None => 0,
    }
}

extern "C" fn read_pixels(
    texture: u64,
    x: i32,
    y: i32,
    width: i32,
    height: i32,
    float: i32,
    out: *mut NativeBuffer,
) -> i32 {
    if let Err(error) = handle::plain(texture, "read_pixels") {
        tracing::error!("{error}");
        return 0;
    }
    match state::backend().read_pixels(texture, [x, y, width, height], float != 0) {
        Some(pixels) => {
            unsafe { *out = NativeBuffer::from_vec(pixels) };
            1
        }
        None => 0,
    }
}

#[allow(clippy::too_many_arguments)]
// Read flags: bit 0 selects float pixels, bit 1 selects the current attachment for ReadPixels.
extern "C" fn read_texture(
    texture: u64,
    mip: i32,
    layer: i32,
    x: i32,
    y: i32,
    width: i32,
    height: i32,
    float: i32,
    out: *mut NativeBuffer,
) -> i32 {
    if let Err(error) = handle::plain(texture, "read_texture") {
        tracing::error!("{error}");
        return 0;
    }
    if mip < 0 || layer < 0 {
        return 0;
    }
    match state::backend().read_texture(
        texture,
        mip as u32,
        layer as u32,
        [x, y, width, height],
        float & 1 != 0,
        float & 2 != 0,
    ) {
        Some(pixels) => {
            unsafe { *out = NativeBuffer::from_vec(pixels) };
            1
        }
        None => 0,
    }
}

