/// The managed side of [`NativeApi`] is generated from this file: `NativeApi.g.cs` must be what
/// this test writes (`UNBOUND_BLESS=1 cargo test -p unbound-runtime native_api` rewrites it).
#[cfg(test)]
mod generated {
    use std::collections::HashMap;
    use std::fmt::Write;
    use std::path::Path;

    const OUTPUT: &str = "managed/UnityEngine/Runtime/NativeApi.g.cs";

    fn docs(attrs: &[syn::Attribute]) -> Vec<String> {
        attrs
            .iter()
            .filter_map(|a| match &a.meta {
                syn::Meta::NameValue(nv) if nv.path.is_ident("doc") => match &nv.value {
                    syn::Expr::Lit(syn::ExprLit {
                        lit: syn::Lit::Str(s),
                        ..
                    }) => Some(s.value()),
                    _ => None,
                },
                _ => None,
            })
            .map(|line| {
                line.strip_prefix(' ')
                    .unwrap_or(&line)
                    .replace('&', "&amp;")
                    .replace('<', "&lt;")
                    .replace('>', "&gt;")
            })
            .collect()
    }

    fn pascal(name: &str) -> String {
        name.split('_')
            .map(|part| {
                let mut chars = part.chars();
                chars
                    .next()
                    .map(|c| c.to_ascii_uppercase().to_string() + chars.as_str())
                    .unwrap_or_default()
            })
            .collect()
    }

    /// A Rust FFI type as C# writes it; `aliases` are the named function types.
    fn cs_type(ty: &syn::Type, aliases: &HashMap<String, syn::TypeBareFn>) -> String {
        match ty {
            syn::Type::Ptr(p) => format!("{}*", cs_type(&p.elem, aliases)),
            syn::Type::BareFn(f) => function(f, aliases),
            syn::Type::Path(p) => {
                let last = p.path.segments.last().expect("a type name");
                let name = last.ident.to_string();
                if name == "Option" {
                    // A nullable function pointer: C# function pointers are nullable already.
                    let syn::PathArguments::AngleBracketed(args) = &last.arguments else {
                        panic!("Option without its argument")
                    };
                    let Some(syn::GenericArgument::Type(inner)) = args.args.first() else {
                        panic!("Option without its argument")
                    };
                    return cs_type(inner, aliases);
                }
                if let Some(f) = aliases.get(&name) {
                    return function(f, aliases);
                }
                match name.as_str() {
                    "u8" => "byte",
                    "i8" => "sbyte",
                    "u16" => "ushort",
                    "i16" => "short",
                    "u32" => "uint",
                    "i32" => "int",
                    "u64" => "ulong",
                    "i64" => "long",
                    "f32" => "float",
                    "f64" => "double",
                    "usize" => "nuint",
                    "isize" => "nint",
                    "c_void" => "void",
                    // Structs keep their names on both sides.
                    other => other,
                }
                .to_string()
            }
            _ => panic!(
                "no C# form for a field type of NativeApi (pointers, numbers, structs and functions only)"
            ),
        }
    }

    fn function(f: &syn::TypeBareFn, aliases: &HashMap<String, syn::TypeBareFn>) -> String {
        let mut types: Vec<String> = f.inputs.iter().map(|a| cs_type(&a.ty, aliases)).collect();
        types.push(match &f.output {
            syn::ReturnType::Default => "void".into(),
            syn::ReturnType::Type(_, ty) => cs_type(ty, aliases),
        });
        format!("delegate* unmanaged<{}>", types.join(", "))
    }

    fn generate(root: &Path) -> String {
        let read = |file: &str| {
            syn::parse_file(&std::fs::read_to_string(root.join(file)).unwrap()).unwrap()
        };
        let api = read("crates/unbound-runtime/src/native_api.rs");
        let mut aliases = HashMap::new();
        for item in read("crates/unbound-runtime/src/audio/protocol.rs").items {
            if let syn::Item::Type(t) = item
                && let syn::Type::BareFn(f) = *t.ty
            {
                aliases.insert(t.ident.to_string(), f);
            }
        }
        let mut version = None;
        let mut fields = None;
        for item in &api.items {
            match item {
                syn::Item::Const(c) if c.ident == "NATIVE_API_VERSION" => {
                    if let syn::Expr::Lit(syn::ExprLit {
                        lit: syn::Lit::Int(n),
                        ..
                    }) = &*c.expr
                    {
                        version = Some(n.base10_digits().to_string());
                    }
                }
                syn::Item::Struct(s) if s.ident == "NativeApi" => fields = Some(s.fields.clone()),
                _ => {}
            }
        }
        let (version, fields) = (
            version.expect("NATIVE_API_VERSION"),
            fields.expect("NativeApi"),
        );
        let mut out = String::new();
        out.push_str(
            "// <auto-generated/>\n\
             // Generated from crates/unbound-runtime/src/native_api.rs; do not edit by hand. After changing\n\
             // `NativeApi` there, run `UNBOUND_BLESS=1 cargo test -p unbound-runtime native_api`.\n\
             namespace Unbound.Runtime\n{\n",
        );
        out.push_str(
            "    /// <summary>\n    /// The functions the native side (Rust) gives the engine at start, in the layout of\n    \
             /// `NativeApi` in `unbound-runtime/src/native_api.rs`; both sides check <see cref=\"Version\"/>.\n    \
             /// </summary>\n    [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]\n    \
             internal unsafe struct NativeApi\n    {\n",
        );
        writeln!(
            out,
            "        internal const uint CurrentVersion = {version};\n"
        )
        .unwrap();
        for field in &fields {
            let name = field.ident.as_ref().expect("a named field").to_string();
            let lines = docs(&field.attrs);
            match lines.len() {
                0 => {}
                1 => writeln!(out, "        /// <summary>{}</summary>", lines[0]).unwrap(),
                _ => {
                    out.push_str("        /// <summary>\n");
                    for line in &lines {
                        writeln!(out, "        /// {line}").unwrap();
                    }
                    out.push_str("        /// </summary>\n");
                }
            }
            let ty = if name == "version" {
                "uint".into()
            } else {
                cs_type(&field.ty, &aliases)
            };
            writeln!(out, "        internal {ty} {};", pascal(&name)).unwrap();
        }
        out.push_str("    }\n}\n");
        out
    }

    #[test]
    fn native_api_matches_the_managed_side() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let generated = generate(&root);
        let path = root.join(OUTPUT);
        if std::env::var_os("UNBOUND_BLESS").is_some() {
            std::fs::write(&path, &generated).unwrap();
            return;
        }
        let current = std::fs::read_to_string(&path).unwrap_or_default();
        assert!(
            current == generated,
            "{OUTPUT} is not what native_api.rs describes: run \
             `UNBOUND_BLESS=1 cargo test -p unbound-runtime native_api`"
        );
    }
}
